-- 3. Người dùng demo — ĐÃ XÓA
--    Không seed user demo. Admin đầu tiên đăng ký qua POST /api/v1/auth/setup-admin.
--    Các user khác do admin tạo qua POST /api/v1/admin/users.
-- ---------------------------------------------------------------------------
-- 4. Gán quyền cho từng vai trò (RBAC)
-- ---------------------------------------------------------------------------
-- Công dân: tạo báo cáo + xem báo cáo của mình
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.code='citizen' AND p.code IN ('report.create','report.view_own')
ON CONFLICT DO NOTHING;

-- Cán bộ thụ lý: xem/cập nhật hồ sơ, lập biên bản
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.code='case_handler' AND p.code IN
  ('case.view','case.update','bien_ban.create','khac_phuc.manage')
ON CONFLICT DO NOTHING;

-- Cán bộ xác minh: xem/cập nhật hồ sơ, phân loại
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.code='verifier' AND p.code IN ('case.view','case.update','case.assign')
ON CONFLICT DO NOTHING;

-- Lãnh đạo: xem hồ sơ, phê duyệt quyết định, thống kê
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.code='leader' AND p.code IN
  ('case.view','case.approve','quyet_dinh.issue','report.statistics','gis.manage')
ON CONFLICT DO NOTHING;

-- Quản trị: toàn bộ quyền
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r, permissions p
WHERE r.code='admin'
ON CONFLICT DO NOTHING;

COMMIT;
